def transform(grid):
    h, w = len(grid), len(grid[0])
    background = 9

    counts = {}
    for row in grid:
        for v in row:
            if v != background:
                counts[v] = counts.get(v, 0) + 1
    line = max(counts, key=counts.get)

    # Grid lines are the rows/columns containing many line-colored cells.
    rows = [r for r in range(h) if grid[r].count(line) >= w * 0.5]
    cols = [c for c in range(w) if sum(grid[r][c] == line for r in range(h)) >= h * 0.5]

    # Include marked intersections on horizontal lines, even if their column
    # is not itself a full-height grid line.
    marked_cols = set(cols)
    for r in rows:
        for c in range(w):
            if grid[r][c] not in (line, background):
                marked_cols.add(c)
    cols = sorted(marked_cols)

    # Keep only the part of the lattice containing marked intersections.
    rows = [r for r in rows if any(grid[r][c] not in (line, background) for c in cols)]
    cols = [c for c in cols if any(grid[r][c] not in (line, background) for r in rows)]

    out = []
    for i in range(len(rows) - 1):
        outrow = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]
            ]
            if corners[0] not in (line, background) and all(v == corners[0] for v in corners):
                outrow.append(corners[0])
            else:
                outrow.append(background)
        out.append(outrow)
    return out
